package ltnc.auction.server;
import static org.junit.jupiter.api.Assertions.*; import java.math.BigDecimal; import java.nio.file.Files; import java.time.Instant; import java.util.List; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.io.TempDir; import java.nio.file.Path; import ltnc.auction.common.model.*; import ltnc.auction.server.persistence.AuctionStore;
class AuctionStoreTest {@TempDir Path temp; @Test void savesAndLoadsAuction(){var store=new AuctionStore(temp.resolve("data.ser"));var item=new Art("i","art","desc","seller",BigDecimal.TEN);var a=new Auction("a",item,BigDecimal.TEN,BigDecimal.ONE,Instant.now().minusSeconds(1),Instant.now().plusSeconds(60));store.save(List.of(a));var loaded=store.load();assertEquals(1,loaded.size());assertEquals("a",loaded.get(0).getId());}}
